import { useEffect, useState } from "react";

export default function App() {
  const [count, setCount] = useState(0);
  console.log("render App");

  useEffect(() => {
    const observer = new MutationObserver((records) => {
      for (const record of records) {
        console.log(`DOM change: ${record.type} "${record.target.textContent}"`);
      }
    });
    observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true });
    return () => observer.disconnect();
  }, []);

  return (
    <main>
      <h1>Trailhead</h1>
      <CartBadge count={count} />
      <button type="button" onClick={() => setCount(count + 1)}>
        Add to cart
      </button>
      <Footer />
    </main>
  );
}

type CartBadgeProps = { count: number };

function CartBadge({ count }: CartBadgeProps) {
  console.log("render CartBadge");
  return <p>Cart: {count}</p>;
}

function Footer() {
  console.log("render Footer");
  return <footer>Free shipping on orders over $50</footer>;
}

