  );
}

type ScrollProgressProps = { children: ReactNode };

function ScrollProgress({ children }: ScrollProgressProps) {
  const [percent, setPercent] = useState(0);
  console.log("render ScrollProgress");

  return (
    <div
      className="scroll-panel"
      onScroll={(event) => {
        const panel = event.currentTarget;
        const max = panel.scrollHeight - panel.clientHeight;
        setPercent(Math.round((panel.scrollTop / max) * 100));
      }}
    >
      <progress max={100} value={percent} aria-label="Scrolled" />
      {children}
    </div>
  );
}

