import { Activity, useEffect, useState } from "react";

type Tab = "details" | "reviews";

export function ProductTabs() {
  const [tab, setTab] = useState<Tab>("details");

  return (
    <section>
      <div role="tablist">
        <button type="button" role="tab" aria-selected={tab === "details"} onClick={() => setTab("details")}>
          Details
        </button>
        <button type="button" role="tab" aria-selected={tab === "reviews"} onClick={() => setTab("reviews")}>
          Reviews
        </button>
      </div>
      <Activity mode={tab === "details" ? "visible" : "hidden"}>
        <p>A freestanding two-person tent with two doors.</p>
      </Activity>
      <Activity mode={tab === "reviews" ? "visible" : "hidden"}>
        <ReviewDraft />
      </Activity>
    </section>
  );
}

function ReviewDraft() {
  const [draft, setDraft] = useState("");

  useEffect(() => {
    console.log("ReviewDraft effect: setup");
    return () => console.log("ReviewDraft effect: cleanup");
  }, []);

  return (
    <label>
      Your review
      <textarea value={draft} onChange={(event) => setDraft(event.target.value)} />
    </label>
  );
}
